   RADIO_PL_STATIONS.forEach((s,i)=>{const b=document.createElement('button');b.className='station';b.setAttribute('aria-label','Odtwórz '+s.name);const img=document.createElement('img');img.src=s.logo;img.alt='';const label=document.createElement('span');label.textContent=s.name;b.append(img,label);b.onclick=()=>this.play(s);r.querySelector('.stations').append(b);});
